mapper.select:
select credit_id, user_id, credit_score, dispute_count, ban_until, ban_reason, last_update
from user_credit
where user_id = #{userId}

mapper.update:
update user_credit
credit_score = #{creditScore}, dispute_count = #{disputeCount}, ban_until = #{banUntil}, ban_reason = #{banReason}, last_update = now()
where credit_id = #{creditId}
